const memoryReplayRange = `-- name: MemoryReplayRange :many
WITH selected AS (
 SELECT source_event_id FROM memory_event_inbox
 WHERE tenant_id=$1 AND source_event_id>=$2::bigint
   AND source_event_id<=$3::bigint AND (dead_at IS NOT NULL OR completed_at IS NOT NULL)
 ORDER BY source_event_id LIMIT $4::int FOR UPDATE
)
UPDATE memory_event_inbox i SET attempts=0, available_at=now(), completed_at=NULL, dead_at=NULL, error_code=''
FROM selected s WHERE i.tenant_id=$1 AND i.source_event_id=s.source_event_id
RETURNING i.source_event_id
`

type MemoryReplayRangeParams struct {
	TenantID string
	FirstID  int64
	LastID   int64
	MaxRows  int32
}

func (q *Queries) MemoryReplayRange(ctx context.Context, arg MemoryReplayRangeParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, memoryReplayRange,
		arg.TenantID,
		arg.FirstID,
		arg.LastID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var source_event_id int64
		if err := rows.Scan(&source_event_id); err != nil {
			return nil, err
		}
		items = append(items, source_event_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const memorySetPolicy = `-- name: MemorySetPolicy :one
INSERT INTO memory_partition_policies (tenant_id, partition, retention_days, updated_by)
SELECT $1, $2, $3, $4
WHERE $5::bigint=0 OR EXISTS
 (SELECT 1 FROM memory_partition_policies p WHERE p.tenant_id=$1 AND p.partition=$2)
ON CONFLICT (tenant_id, partition) DO UPDATE SET retention_days=EXCLUDED.retention_days, updated_by=EXCLUDED.updated_by,
 revision=memory_partition_policies.revision+1, updated_at=now()
WHERE memory_partition_policies.revision=$5::bigint
RETURNING revision
`

type MemorySetPolicyParams struct {
	TenantID         string
	Partition        string
	RetentionDays    int32
	UpdatedBy        int64
	ExpectedRevision int64
}

func (q *Queries) MemorySetPolicy(ctx context.Context, arg MemorySetPolicyParams) (int64, error) {
	row := q.db.QueryRow(ctx, memorySetPolicy,
		arg.TenantID,
		arg.Partition,
		arg.RetentionDays,
		arg.UpdatedBy,
		arg.ExpectedRevision,
	)
	var revision int64
	err := row.Scan(&revision)
	return revision, err
}
